/* TRINCA 360 — aplicativo 100% front-end. Dados locais no aparelho. */
(()=>{
'use strict';
const DB=window.TRINCA_DATA;
const KEY='trinca360-state-v1';
const DEFAULTS={profile:{name:'',age:43,weight:'',height:'',waist:'',experience:'retomando',goal:'definicao',sessionLength:'30',foodStyle:'geral',restrictions:'',startDate:localDate()},sessions:[],measures:[],walks:[],habits:{},drafts:{},hydration:{},reminders:{enabled:false,water:true,snack:true,waterEvery:120,start:'08:00',end:'20:00',snackAM:'10:00',snackPM:'16:00',notifications:false},seenReminders:{},updatedAt:null};
let store=load();
let ui={page:'home',day:'A',selectedExercise:null,sessionSeconds:0,sessionRunning:false,restSeconds:60,restRunning:false,installPrompt:null};
let tickId=null,toastId=null;
const $=sel=>document.querySelector(sel);
const esc=str=>String(str??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtNum=n=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(n);
const fmtDate=iso=>{const p=String(iso||'').split('-').map(Number);if(p.length!==3||!p[0])return '—';return new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date(p[0],p[1]-1,p[2]));};
function localDate(dt=new Date()){const pad=n=>String(n).padStart(2,'0');return `${dt.getFullYear()}-${pad(dt.getMonth()+1)}-${pad(dt.getDate())}`;}
function localDateFrom(iso){const [y,m,d]=iso.split('-').map(Number);return new Date(y,m-1,d);}
function weekStart(dt=new Date()){const d=new Date(dt.getFullYear(),dt.getMonth(),dt.getDate());d.setDate(d.getDate()-(d.getDay()+6)%7);return localDate(d);}
function dayFor(dt=new Date()){return ({1:'A',3:'B',5:'C'})[dt.getDay()]||null;}
function nextTraining(){const today=new Date(), day=today.getDay();for(let shift=0;shift<8;shift++){const d=new Date(today.getFullYear(),today.getMonth(),today.getDate()+shift), key=dayFor(d);if(key)return {key, date:localDate(d),today:shift===0};}return {key:'A',date:localDate()};}
function load(){try{const raw=JSON.parse(localStorage.getItem(KEY));if(raw&&typeof raw==='object'&&Array.isArray(raw.sessions)&&Array.isArray(raw.measures)&&Array.isArray(raw.walks))return {...structuredClone(DEFAULTS),...raw,profile:{...DEFAULTS.profile,...raw.profile},drafts:raw.drafts&&typeof raw.drafts==='object'?raw.drafts:{},habits:raw.habits&&typeof raw.habits==='object'?raw.habits:{},hydration:raw.hydration&&typeof raw.hydration==='object'?raw.hydration:{},reminders:{...DEFAULTS.reminders,...(raw.reminders||{})},seenReminders:raw.seenReminders&&typeof raw.seenReminders==='object'?raw.seenReminders:{}};}catch(e){console.warn('Dados indisponíveis',e);}return structuredClone(DEFAULTS);}
function save(){store.updatedAt=new Date().toISOString();try{localStorage.setItem(KEY,JSON.stringify(store));return true;}catch(e){notify('Armazenamento bloqueado. Exporte um backup para preservar os registros.');return false;}}
function notify(msg){const root=$('#toast-root');root.innerHTML=`<div class="toast">${esc(msg)}</div>`;clearTimeout(toastId);toastId=setTimeout(()=>root.innerHTML='',3300);}
function setNav(page){ui.page=page;render();window.scrollTo({top:0,behavior:'instant'});}
function setDay(key){ui.day=key;setNav('workouts');}
function sessionName(s){return s.type==='avulso'||s.day==='AVULSO'?`Treino avulso · ${esc((s.groups||[]).join(' + ')||'Musculação')}`:`Treino ${esc(s.day)} · ${esc((DB.programs[s.day]?.name)||'Musculação')}`;}

function weekNumber(){const start=localDateFrom(store.profile.startDate||localDate());const now=localDateFrom(localDate());return Math.max(1,Math.floor((now-start)/604800000)+1);}
function cycleNumber(){return Math.floor((weekNumber()-1)/12)+1;}
function phaseWeek(){return ((weekNumber()-1)%12)+1;}
function program(day){return (cycleNumber()%2===0?DB.rotations:DB.programs)[day];}
function mainSets(){if(phaseWeek()<=2&&store.profile.experience!=='ativo')return 1;return store.profile.sessionLength==='60'?4:store.profile.sessionLength==='45'?4:3;}
function setsFor(day,id){if(phaseWeek()<=2&&store.profile.experience!=='ativo')return 1;return store.profile.sessionLength==='60'?4:(program(day).exercises[0]===id?mainSets():(store.profile.sessionLength==='45'?3:2));}
function repFor(id){const r=DB.exercises[id].reps;if(/s|lado|perna/.test(r))return r;return phaseWeek()<=2?'10–12':phaseWeek()<=6?'10–12':phaseWeek()<=10?'8–10':'10–12';}
function rirGoal(){return phaseWeek()<=2? '3–4':phaseWeek()<=6?'2–3':phaseWeek()<=10?'1–2':'3–4';}
function restGoal(){return store.profile.sessionLength==='60'?'60–120 s':store.profile.sessionLength==='45'?'60–90 s':'45–75 s';}
function phaseTitle(){const x=phaseWeek();return DB.phases[x<=2?0:x<=6?1:x<=10?2:3];}
function nextLoadHint(day,id){const old=[...store.sessions].reverse().find(a=>a.exercises&&a.exercises[id]&&Number(a.exercises[id].weight)>0);if(!old)return 'Comece com carga confortável e refine a técnica.';const r=old.exercises[id];if(r.rir!=null&&Number(r.rir)>=3 && Number(r.setsDone)>=2)return `Última carga: ${esc(r.weight)} kg, com folga relatada. Se executou todas as repetições com técnica, pode avaliar pequeno aumento (2–5%).`;if(r.rir!=null&&Number(r.rir)<=1)return `Última carga: ${esc(r.weight)} kg. Mantenha ou reduza para recuperar a execução.`;return `Última carga registrada: ${esc(r.weight)} kg. Progrida apenas com movimento controlado.`;}

function draftFor(day){if(!store.drafts[day]||typeof store.drafts[day]!=='object')store.drafts[day]={};const obj=store.drafts[day];for(const exId of program(day).exercises){if(!obj[exId]||!Array.isArray(obj[exId].sets))obj[exId]={sets:[],weight:'',rir:''};}return obj;}
function completedSets(day){const d=draftFor(day);let count=0;for(const id of program(day).exercises)count+=d[id].sets.slice(0,setsFor(day,id)).filter(Boolean).length;return count;}
function targetSets(day){return program(day).exercises.reduce((a,id)=>a+setsFor(day,id),0);}
function sessionsThisWeek(){const w=weekStart();return store.sessions.filter(s=>s.date>=w);}
function cardioThisWeek(){const w=weekStart();return sessionsThisWeek().reduce((acc,s)=>acc+(Number(s.cardioMin)||0),0)+store.walks.filter(walk=>walk.date>=w).reduce((acc,s)=>acc+(Number(s.minutes)||0),0);}
function titleBlock(eye,title,sub){return `<div class="eyebrow">${eye}</div><h1>${title}</h1>${sub?`<p class="muted small">${sub}</p>`:''}`;}
function commonNotice(){return `<div class="notice warning"><span style="font-size:19px">⚕</span><div>Adapte o exercício à sua condição e aos aparelhos disponíveis. Se houver doença relevante, dor persistente ou longo período de sedentarismo, procure orientação de profissional habilitado. Pare diante de dor no peito, tontura ou falta de ar incomum.</div></div>`;}
function home(){const next=nextTraining(),plan=program(next.key),week=sessionsThisWeek(),min=cardioThisWeek(),name=store.profile.name?`Olá, ${esc(store.profile.name.split(' ')[0])}!`:'Seu treino, seu ritmo.';return `
  <section class="hero"><div class="eyebrow">SEU PROJETO DE EVOLUÇÃO</div><h1>${name}<br>Corpo forte.<br>Rotina possível.</h1><p class="subtitle">3 treinos por semana · ${store.profile.sessionLength} minutos por sessão · evolução real, sem promessas mágicas.</p><button class="btn primary cta" data-action="open-day" data-day="${next.key}">Começar treino ${next.key} <span aria-hidden="true">↗</span></button></section>
  <div class="quick-actions"><button class="btn outline" data-action="go-help">❔ Manual e ajuda</button><button class="btn outline" data-action="go-avulso">＋ Treino avulso</button></div>
  <div class="grid-two spaced"><div class="metric"><div class="mini-icon">✦</div><div class="number">${week.length}<span style="font-size:13px;color:var(--muted)"> / 3</span></div><div class="label">Sessões de força nesta semana (inclui avulsos)</div></div><div class="metric"><div class="mini-icon">◷</div><div class="number">${min}<span style="font-size:13px;color:var(--muted)"> min</span></div><div class="label">Cardio registrado na semana</div></div></div>
  <div class="section-heading"><h2>Próximo treino</h2><span class="badge-date">${next.today?'Hoje':fmtDate(next.date)}</span></div>
  ${dayCard(next.key,true)}
  <div class="section-heading"><h2>Seu plano semanal</h2><button class="link-btn" data-action="go-workouts">Ver treinos →</button></div>
  <div class="stack">${['A','B','C'].map(k=>dayCard(k,false)).join('')}</div>
  <div class="section-heading"><h2>Distribuição do tempo</h2></div><div class="card flat"><div class="timeline"><div></div><div></div><div></div><div></div></div><div class="time-parts"><div><strong>${store.profile.sessionLength==='30'?4:5} min</strong><span>Aquecimento</span></div><div><strong>${store.profile.sessionLength==='30'?20:store.profile.sessionLength==='45'?32:45} min</strong><span>Musculação</span></div><div><strong>${store.profile.sessionLength==='30'?4:store.profile.sessionLength==='45'?6:8} min</strong><span>Cardio</span></div><div><strong>2 min</strong><span>Recuperação</span></div></div><p class="footnote" style="margin:13px 0 0">Os 4 minutos de cardio por treino são um ponto de partida e não substituem a recomendação semanal de atividade aeróbica.</p></div>
  <div class="section-heading"><h2>Seu ciclo evolutivo</h2></div><div class="next-banner"><div class="eyebrow">CICLO ${cycleNumber()} · SEMANA ${phaseWeek()} DE 12</div><strong>${phaseTitle().title}</strong><p class="small muted" style="margin:7px 0 0">${phaseTitle().body} Na semana 13 inicia uma rotação de exercícios. Confirme suas condições com um profissional antes de aumentar cargas.</p><div class="pill-row" style="margin-top:10px"><span class="pill">${store.profile.sessionLength} min</span><span class="pill blue">Esforço-alvo: RIR ${rirGoal()}</span></div></div>
  <div class="section-heading"><h2>Minha avaliação</h2><button class="link-btn" data-action="go-profile">Atualizar dados →</button></div>${assessmentCard()}
  <p class="footnote" style="margin:10px 0 0">${goalAdvice()}</p><div class="section-heading"><h2>Hidratação hoje</h2><button class="link-btn" data-action="go-nutrition">Registrar água →</button></div>${waterCard()}
  <div class="section-heading"><h2>Treino com evidência</h2></div><div class="notice"><span style="font-size:22px">✓</span><div>Programa baseado em princípios de instituições de referência como ACSM, OMS e Ministério da Saúde. <button class="link-btn" data-action="go-nutrition" style="display:block;text-align:left;margin-top:2px">Ver orientações e fontes →</button></div></div>`;}
function dayCard(key,highlight=false){const p=program(key),records=sessionsThisWeek().filter(s=>s.day===key);return `<button class="day-card ${highlight?'selected':''}" data-action="open-day" data-day="${key}" style="text-align:left;width:100%"><div class="day-icon" style="background:${p.accent}"><small>TREINO</small>${key}</div><div class="data"><h3>${p.name}</h3><p>${p.subtitle}</p><div class="pill-row"><span class="mini-tag">${p.day}</span><span class="mini-tag">${store.profile.sessionLength} min</span>${records.length?'<span class="pill" style="padding:4px 7px">✓ feito</span>':''}</div></div><span class="arrow">›</span></button>`;}
function workoutPage(){const day=ui.day,p=program(day),d=draftFor(day),target=targetSets(day),done=completedSets(day),pct=done/target*100;return `
  <div class="eyebrow">CICLO ${cycleNumber()} · SEMANA ${phaseWeek()} DE 12</div><h1>Vamos treinar.</h1><div class="tab-row">${Object.keys(DB.programs).map(k=>`<button class="tab-pill ${day===k?'active':''}" data-action="open-day" data-day="${k}">Treino ${k}</button>`).join('')}</div>
  <section class="program-banner" style="background:${p.accent}"><div class="top-info"><span class="pill dark">${p.day}</span><span class="pill dark">${store.profile.sessionLength} min</span></div><h1>Treino ${day} · ${p.name}</h1><p>${p.subtitle}</p></section>
  <div class="section-heading"><h2>Prescrição de hoje</h2><span class="badge-date">${done}/${target} séries</span></div>
  <div class="card flat"><div class="pill-row"><span class="pill blue">${phaseTitle().title}</span><span class="pill">RIR ${rirGoal()}</span><span class="pill gray">Pausa ${restGoal()}</span></div><div class="progress-track"><div style="width:${pct}%"></div></div><p class="small muted" style="margin:11px 0 0">${goalAdvice()} RIR = repetições que você ainda conseguiria fazer ao final da série. RIR 2 significa parar com cerca de 2 repetições possíveis. Nunca priorize carga acima da técnica.</p>${store.profile.sessionLength==='30'?'<p class="footnote">Modo 30 min: 3 séries no movimento principal e 2 nos demais (exceto adaptação inicial). Para 4 séries principais e 3 auxiliares, escolha 45 min; para até 4 em todos, escolha 60 min.</p>':'<p class="footnote">Modo estendido: consulte a quantidade de séries exibida em cada cartão; ajuste as pausas ao seu fôlego.</p>'}</div>
  <div class="section-heading"><h2>Relógios do treino</h2></div><div class="timer-panel"><div class="timer-box"><p>⏱ Sessão</p><div id="clock-session" class="time">${toClock(ui.sessionSeconds)}</div><div class="timer-controls"><button data-action="session-toggle">${ui.sessionRunning?'Pausar':'Iniciar'}</button><button class="secondary" data-action="session-reset">↺</button></div></div><div class="timer-box"><p>◷ Intervalo</p><div id="clock-rest" class="time">${toClock(ui.restSeconds)}</div><div class="timer-controls"><button data-action="rest-toggle">${ui.restRunning?'Pausar':'Iniciar'}</button><button class="secondary" data-action="rest-reset">↺</button></div></div></div>
  <div class="section-heading"><h2>Exercícios e metas</h2><span class="muted small">Toque em “Como fazer”</span></div>
  ${p.exercises.map((id,i)=>exerciseCard(day,id,i)).join('')}
  <div class="card"><h3>Fechar sessão</h3><p class="small muted">Marque as séries efetivamente realizadas. Registre carga e RIR para apoiar a próxima sessão.</p><button class="btn teal block" data-action="finish-start" data-day="${day}">Registrar este treino ✓</button></div>
  <div style="margin-top:13px">${commonNotice()}</div>`;}
function exerciseCard(day,id,i){const ex=DB.exercises[id],draft=draftFor(day)[id],n=setsFor(day,id),done=draft.sets.slice(0,n).filter(Boolean).length;return `<article class="exercise-item"><div class="exercise-main"><img loading="lazy" class="exercise-img" src="assets/exercises/${ex.image}.svg" alt="Ilustração esquemática de ${esc(ex.name)}"><div class="exercise-content"><div class="eyebrow" style="margin:0;font-size:9px">${String(i+1).padStart(2,'0')} · ${esc(ex.group)} ${i===0?'· PRINCIPAL':''}</div><h3>${esc(ex.name)}</h3><div class="subtitle">${esc(ex.equipment)}</div><div class="exercise-meta"><span class="mini-tag emphasis">${n} ${n===1?'série':'séries'} × ${esc(repFor(id))}</span><span class="mini-tag">${done}/${n} feitas</span></div></div></div><div class="exercise-tools"><div class="set-dots">${Array.from({length:n},(_,j)=>`<button class="set-btn ${draft.sets[j]?'done':''}" data-action="set-toggle" data-day="${day}" data-id="${id}" data-index="${j}" aria-pressed="${!!draft.sets[j]}" aria-label="Marcar série ${j+1} de ${esc(ex.name)}">${draft.sets[j]?'✓':'S'+(j+1)}</button>`).join('')}</div><div class="exercise-actions"><button class="btn ghost smallbtn" data-action="exercise-detail" data-id="${id}" data-day="${day}">▶ Como fazer</button></div></div><div class="grid-two" style="margin-top:12px"><label class="mini-field">Carga (kg)<input aria-label="Carga de ${esc(ex.name)} em quilogramas" data-input="weight" data-day="${day}" data-id="${id}" type="number" min="0" max="500" step="0.5" value="${esc(draft.weight||'')}" placeholder="kg" inputmode="decimal"></label><label class="mini-field">RIR real da última série<select aria-label="RIR real de ${esc(ex.name)}" data-input="rir" data-day="${day}" data-id="${id}"><option value="" ${draft.rir===''?'selected':''}>Escolher</option>${[0,1,2,3,4,5].map(v=>`<option value="${v}" ${String(draft.rir)===String(v)?'selected':''}>${v}${v===5?'+':''}</option>`).join('')}</select></label></div><p class="footnote" style="margin:10px 0 0">${nextLoadHint(day,id)}</p></article>`;}

function workoutListPage(){return `${titleBlock('TREINAMENTO','Seus três treinos.','Segunda, quarta e sexta: escolha uma sessão e avance no seu ritmo.')}<div class="card flat"><h3>Treinou fora da ficha A/B/C?</h3><p class="small muted">Registre peito + bíceps, por exemplo, e inclua os minutos de esteira no mesmo lançamento. A sessão contará na frequência semanal, mas não marcará A/B/C como feita.</p><button class="btn teal block" data-action="go-avulso">＋ Registrar treino avulso</button></div><div class="section-heading"><h2>Fichas planejadas</h2></div><div class="stack">${Object.keys(DB.programs).map(k=>dayCard(k)).join('')}</div><div class="section-heading"><h2>Progressão em 8 semanas</h2></div><div class="stack">${DB.phases.map((p,i)=>`<div class="card flat"><div class="pill ${weekNumber()>=1+2*i&&weekNumber()<=2+2*i?'blue':'gray'}">Semanas ${p.weeks}</div><h3 style="margin:10px 0 7px">${p.title}</h3><p class="small muted" style="margin:0">${p.body}</p></div>`).join('')}</div>`;}
function avulsoPage(){return `${titleBlock('REGISTRO LIVRE','Treino avulso.','Registre uma sessão que você realmente realizou fora das fichas A, B ou C.')}
  <div class="notice info"><span>✓</span><div>Exemplo: peito + bíceps e 10 minutos de esteira = <strong>1 sessão de força + 10 minutos de cardio</strong>. A musculação será contabilizada nas sessões da semana, sem marcar uma ficha planejada como concluída. Registre cada minuto de cardio apenas uma vez.</div></div>
  <div class="card" style="margin-top:14px"><form id="avulso-form"><div class="form-field"><label for="av-date">Data em que treinou</label><input id="av-date" type="date" name="date" max="${localDate()}" value="${localDate()}" required></div><div class="form-field"><label>Quais grupos musculares trabalhou? (marque pelo menos um)</label><div class="group-choices">${['Peito','Costas','Bíceps','Tríceps','Pernas','Ombros','Abdômen','Glúteos','Corpo inteiro','Outro'].map(g=>`<label class="group-choice"><input type="checkbox" name="groups" value="${g}"> ${g}</label>`).join('')}</div></div><div class="grid-two"><div class="form-field"><label for="av-strength">Musculação (min)</label><input id="av-strength" name="strength" type="number" min="1" max="300" step="1" placeholder="Ex.: 25" required></div><div class="form-field"><label for="av-cardio">Cardio na mesma sessão (min)</label><input id="av-cardio" name="cardio" type="number" min="0" max="300" step="1" value="0" required></div></div><div class="form-field"><label for="av-cardio-kind">Tipo de cardio (se houver)</label><select id="av-cardio-kind" name="cardioType"><option>Esteira</option><option>Caminhada ao ar livre</option><option>Bicicleta</option><option>Elíptico</option><option>Outro</option></select></div><div class="form-field"><label for="av-note">Exercícios, séries e observações (opcional)</label><textarea id="av-note" name="note" maxlength="300" placeholder="Ex.: Supino 3 × 10; rosca bíceps 3 × 12; esteira 10 min"></textarea></div><p class="footnote">Informe o tempo real, não o planejado. Se incluiu a esteira aqui, NÃO a registre novamente em Cardio extra.</p><button class="btn teal block" type="submit">✓ Salvar treino avulso</button></form></div><button class="btn outline block" style="margin-top:12px" data-action="go-progress">Ver meu histórico →</button><div style="margin-top:13px">${commonNotice()}</div>`;}

function progressPage(){const total=store.sessions.length,min=cardioThisWeek(),allSessions=[...store.sessions].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,10);return `
  ${titleBlock('SEUS RESULTADOS','Evolução que se vê.','Seu diário particular de consistência, cargas e medidas.')}<div class="grid-two"><div class="metric"><div class="mini-icon">🏋</div><div class="number">${total}</div><div class="label">Sessões registradas</div></div><div class="metric"><div class="mini-icon">⚡</div><div class="number">${min} <span style="font-size:12px">min</span></div><div class="label">Cardio nesta semana</div></div></div>
  <div class="section-heading"><h2>Fiz outro treino na academia</h2></div><div class="card flat"><p class="small muted">Seu treino de peito + bíceps também pode entrar no histórico. Informe os grupos, duração e cardio uma única vez.</p><button class="btn teal block" data-action="go-avulso">＋ Registrar treino avulso</button></div>
  <div class="section-heading"><h2>Últimas 8 semanas</h2></div><div class="card"><div class="pill-row"><span class="pill">Meta de frequência: 3 treinos / semana</span></div>${weeklyBars()}<p class="footnote" style="margin-bottom:0">Cada barra mostra a quantidade de sessões registradas na respectiva semana.</p></div>
  <div class="section-heading"><h2>Caminhadas e cardio extra</h2></div><div class="card"><p class="footnote">Use esta área apenas para cardio independente. Se os minutos já estão dentro de uma sessão A/B/C ou avulsa, não repita o lançamento.</p><form id="walk-form"><div class="grid-two"><div class="form-field"><label for="walk-date">Data</label><input id="walk-date" name="date" type="date" max="${localDate()}" required value="${localDate()}"></div><div class="form-field"><label for="walk-min">Minutos realizados</label><input id="walk-min" name="minutes" type="number" min="1" max="600" placeholder="Ex.: 20" required></div></div><div class="form-field"><label for="walk-kind">Atividade</label><select name="type" id="walk-kind"><option>Esteira</option><option>Caminhada ao ar livre</option><option>Bicicleta</option><option>Elíptico</option><option>Outro</option></select></div><button class="btn teal block" type="submit">+ Registrar cardio independente</button></form>${cardioHistory()}<p class="footnote" style="margin:13px 0 0">A OMS recomenda cerca de 150–300 min/semana de atividade aeróbica moderada para adultos, além da força. O registro não mede intensidade.</p></div>
  <div class="section-heading"><h2>Avaliação atual</h2></div>${assessmentCard()}
  <div class="section-heading"><h2>Peso e cintura</h2></div><div class="card"><form id="measure-form"><div class="form-field"><label for="measure-date">Data da avaliação</label><input id="measure-date" type="date" name="date" max="${localDate()}" required value="${localDate()}"></div><div class="grid-two"><div class="form-field"><label for="measure-weight">Peso (kg)</label><input id="measure-weight" name="weight" type="number" min="20" max="350" step="0.1" placeholder="Opcional"></div><div class="form-field"><label for="measure-waist">Cintura (cm)</label><input id="measure-waist" name="waist" type="number" min="30" max="220" step="0.1" placeholder="Opcional"></div></div><button type="submit" class="btn teal block">Salvar avaliação</button></form><div id="measure-history">${measureHistory()}</div></div>
  <div class="section-heading"><h2>Histórico de treinos</h2></div><div class="card">${allSessions.length?allSessions.map(s=>`<div class="history-row"><div class="pill-row"><div class="history-icon">✓</div><div><strong>${sessionName(s)}</strong><span>${fmtDate(s.date)} · ${esc(s.durationMin)} min ${s.type==='avulso'?`(força ${esc(s.strengthMin)} + cardio ${esc(s.cardioMin)})`:`· ${esc(s.doneSets)} séries · cardio ${esc(s.cardioMin||0)} min`}${s.note?` · ${esc(s.note)}`:''}</span></div></div><span class="status ${s.partial?'partial':'ok'}">${s.type==='avulso'?'Avulso':s.partial?'Parcial':'Feito'}</span></div>`).join(''):`<div class="empty">Seu primeiro treino registrado aparecerá aqui. 💪</div>`}</div>`;}
function cardioHistory(){const arr=[...store.walks].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,8);return arr.length?`<div class="extra-cardio-history"><div class="eyebrow">CARDIO INDEPENDENTE · REGISTROS RECENTES</div>${arr.map(w=>`<div class="history-row"><div><strong>${esc(w.type||'Caminhada / cardio')}</strong><span>${fmtDate(w.date)} · ${esc(w.minutes)} minutos</span></div><button class="btn ghost smallbtn" data-action="remove-cardio" data-id="${esc(w.id)}">Excluir</button></div>`).join('')}</div>`:'';}
function weeklyBars(){const monday=localDateFrom(weekStart());const series=[];for(let i=7;i>=0;i--){const start=new Date(monday);start.setDate(start.getDate()-i*7);const iso=localDate(start);const count=store.sessions.filter(s=>weekStart(localDateFrom(s.date))===iso).length;series.push({count,lab:fmtDate(iso)});}const high=Math.max(3,...series.map(s=>s.count));return `<div class="bars">${series.map(v=>`<div class="bar-col"><strong>${v.count||'·'}</strong><div class="bar ${v.count>=3?'hit':''}" style="height:${Math.max(4,v.count/high*90)}px"></div><span>${v.lab}</span></div>`).join('')}</div>`;}
function measureHistory(){const a=[...store.measures].sort((x,y)=>y.date.localeCompare(x.date)).slice(0,5);return a.length?`<div style="margin-top:13px"><div class="eyebrow">REGISTROS MAIS RECENTES</div>${a.map(m=>`<div class="history-row"><div><strong>${fmtDate(m.date)}</strong><span>${m.weight?fmtNum(m.weight)+' kg':'—'} · ${m.waist?fmtNum(m.waist)+' cm cintura':'—'}</span></div><button class="btn ghost smallbtn" data-action="remove-measure" data-id="${esc(m.id)}">Excluir</button></div>`).join('')}</div>`:'';}
function latestMeasure(){return [...store.measures].sort((a,b)=>b.date.localeCompare(a.date))[0]||null;}
function assessmentCard(){const p=store.profile,m=latestMeasure(),w=Number(m?.weight||p.weight),waist=Number(m?.waist||p.waist),height=Number(p.height),bmi=w&&height? w/((height/100)**2):null;return `<div class="card"><div class="grid-two"><div class="stat-mini"><b>${w?fmtNum(w)+' kg':'—'}</b><span>Peso mais recente</span></div><div class="stat-mini"><b>${waist?fmtNum(waist)+' cm':'—'}</b><span>Cintura abdominal</span></div><div class="stat-mini"><b>${height?height+' cm':'—'}</b><span>Altura</span></div><div class="stat-mini"><b>${bmi?fmtNum(bmi):'—'}</b><span>IMC orientativo</span></div></div><p class="footnote" style="margin:12px 0 0">Meça a cintura sempre no mesmo ponto e horário, sem prender a barriga. IMC e cintura, isoladamente, não definem gordura corporal nem cargas seguras. O plano considera também experiência, duração e esforço registrado.</p></div>`;}
function goalAdvice(){return store.profile.goal==='condicionamento'?'Prioridade declarada: condicionamento. Inclua cardio moderado em dias alternados, avançando gradualmente à recomendação geral da OMS (150–300 min/semana).':store.profile.goal==='forca'?'Prioridade declarada: força e saúde. Progrida cargas com técnica e recuperação, sem buscar falha em todas as séries.':'Prioridade declarada: definição. Desenvolva força, preserve a regularidade e ajuste a alimentação com profissional; a cintura mostra tendência, não percentual de gordura.';}
function waterAmount(){return Math.max(0,Number(store.hydration?.[localDate()]||0));}
function waterCard(){return `<div class="card flat"><div class="water-head"><span style="font-size:27px">💧</span><div><strong>${fmtNum(waterAmount())} ml registrados</strong><p class="footnote" style="margin:2px 0 0">Registro de bebidas, não cálculo da necessidade total individual.</p></div></div><div class="pill-row" style="margin-top:11px"><button class="btn ghost smallbtn" data-action="water-add" data-ml="150">+150 ml</button><button class="btn teal smallbtn" data-action="water-add" data-ml="250">+250 ml</button><button class="btn outline smallbtn" data-action="water-undo">Desfazer 250 ml</button></div><p class="footnote" style="margin:10px 0 0">Adapte sua ingestão à sede, suor, ambiente e orientações clínicas. Evite consumir grandes volumes de uma vez.</p></div>`;}
function parseClock(val){const m=/^(\d{2}):(\d{2})$/.exec(String(val));return m?Number(m[1])*60+Number(m[2]):NaN;}
function reminderSlots(){const r=store.reminders;if(!r.enabled)return [];let slots=[];const start=parseClock(r.start),end=parseClock(r.end),step=Number(r.waterEvery)||120;if(r.water&&Number.isFinite(start)&&Number.isFinite(end)&&start<end){for(let minute=start;minute<=end;minute+=step)slots.push({key:'water-'+minute,minute,msg:'Hora de fazer uma pausa e considerar beber água 💧'});}for(const [type,time] of [['snackAM',r.snackAM],['snackPM',r.snackPM]])if(r.snack){let minute=parseClock(time);if(Number.isFinite(minute))slots.push({key:type,minute,msg:type==='snackAM'?'Pausa da manhã: avalie sua fome e escolha um lanche, se precisar. 🍎':'Pausa da tarde: se sentir fome, faça um lanche nutritivo. 🥛'});}return slots;}
function remindWhenOpen(){const now=new Date(),today=localDate(now),minute=now.getHours()*60+now.getMinutes();if(!store.reminders.enabled)return;const history=store.seenReminders[today]||(store.seenReminders[today]={});let changed=false;for(const slot of reminderSlots()){if(minute>=slot.minute&&minute<slot.minute+3&&!history[slot.key]){history[slot.key]=true;changed=true;notify(slot.msg);if(store.reminders.notifications && 'Notification' in window && Notification.permission==='granted'){try{new Notification('TRINCA 360',{body:slot.msg,icon:'assets/icon-192.png',tag:slot.key});}catch(e){}}}}if(changed)save();}
function icsDate(minute){return String(Math.floor(minute/60)).padStart(2,'0')+String(minute%60).padStart(2,'0')+'00';}
function exportReminders(){const slots=reminderSlots();if(!slots.length){notify('Ative os lembretes e escolha os horários primeiro.');return;}const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z/,'Z');const ymd=localDate().replace(/-/g,'');const escCal=x=>x.replace(/\\/g,'\\\\').replace(/,/g,'\\,').replace(/;/g,'\\;').replace(/\n/g,'\\n');let lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//TRINCA360//AGENDA//PT-BR','CALSCALE:GREGORIAN','METHOD:PUBLISH'];slots.forEach((t,i)=>lines.push('BEGIN:VEVENT','UID:trinca360-'+t.key+'@local','DTSTAMP:'+stamp,'DTSTART:'+ymd+'T'+icsDate(t.minute),'RRULE:FREQ=DAILY','SUMMARY:'+escCal(t.key.startsWith('water')?'TRINCA 360 - Pausa para água':'TRINCA 360 - Pausa para lanche'),'DESCRIPTION:'+escCal(t.msg),'BEGIN:VALARM','ACTION:DISPLAY','DESCRIPTION:'+escCal(t.msg),'TRIGGER:PT0M','END:VALARM','END:VEVENT'));lines.push('END:VCALENDAR');const blob=new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='TRINCA360_Lembretes_Calendario.ics';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('Agenda .ics exportada. Importe no calendário e confirme os alertas no aparelho.');}

function nutritionPage(){const today=localDate(),h=store.habits[today]||{},habits=[['fresh','Baseei refeições em alimentos in natura/minimamente processados'],['produce','Incluí frutas, verduras ou legumes'],['protein','Distribuí fontes de proteína no dia'],['hydration','Observei minha hidratação e sede']];const total=habits.filter(([k])=>h[k]).length,weight=Number(latestMeasure()?.weight||store.profile.weight),veg=store.profile.foodStyle==='vegetariano';let meals=[['🌅','Café da manhã',veg?'Iogurte natural ou vegetal enriquecido + aveia + banana; alternativa: pão integral com pasta de grão-de-bico.':'Ovos + pão ou tapioca + uma fruta; alternativa: iogurte natural com aveia e banana.'],['☀️','Almoço',veg?'Arroz + feijão + tofu/omelete (se consumir) + salada colorida e legumes.':'Arroz + feijão + frango, peixe ou ovos + salada e legumes.'],['🍌','Lanche da tarde (se houver fome)',veg?'Fruta + castanhas; ou sanduíche de homus e tomate.':'Fruta + iogurte natural; ou pão com queijo e fruta.'],['🌙','Jantar',veg?'Sopa de legumes com lentilha; ou arroz, feijão e salada com tofu.':'Omelete com legumes e batata; ou refeição caseira com arroz, feijão e proteína.'],['🌜','Ceia opcional',veg?'Uma fruta, iogurte de sua preferência ou nada, se não houver fome.':'Leite/iogurte natural ou uma fruta, se sentir fome. Não é obrigatório.']];return `
  ${titleBlock('NUTRIÇÃO COM CIÊNCIA','Seu dia no prato.','Exemplos educativos, não prescrição clínica individual. Ajuste horários e porções com nutricionista.')}
  <section class="hero" style="background:#2C5B3C;min-height:195px"><div class="eyebrow">ENERGIA PARA EVOLUIR</div><h1 style="font-size:27px">Comida de verdade.<br>Treino consistente.</h1><p class="subtitle" style="margin-bottom:0">Sugestões de manhã, tarde e noite com alimentos acessíveis no Brasil.</p></section>
  <div class="section-heading"><h2>Exemplos de refeições</h2><button class="link-btn" data-action="go-profile">Preferências →</button></div>
  ${meals.map(([em,label,desc])=>`<div class="meal-card"><div class="meal-emoji">${em}</div><div><strong>${label}</strong><p>${desc}</p></div></div>`).join('')}
  <div class="notice info" style="margin-top:12px"><span>ℹ️</span><div>Não existe horário universal para comer. Lanches são opcionais conforme fome, treino e rotina. Não foram prescritas calorias ou porções com base apenas em peso/altura. ${store.profile.restrictions?'Você registrou restrições/preferências: '+esc(store.profile.restrictions)+'. Confira os ingredientes e procure orientação individual.':''}</div></div>
  <div class="section-heading"><h2>Água durante o dia</h2><span class="badge-date">Registro diário</span></div>${waterCard()}
  <div class="section-heading"><h2>Lembretes de água e lanches</h2></div><div class="card"><form id="reminders-form"><label class="checkbox-line"><input type="checkbox" name="enabled" ${store.reminders.enabled?'checked':''}> Ativar lembretes configurados</label><div class="grid-two" style="margin-top:16px"><label class="mini-field">Início das pausas de água<input type="time" name="start" required value="${esc(store.reminders.start)}"></label><label class="mini-field">Fim das pausas<input type="time" name="end" required value="${esc(store.reminders.end)}"></label></div><div class="form-field"><label>Intervalo de hidratação (lembrete, não obrigação de beber)</label><select name="waterEvery"><option value="120" ${Number(store.reminders.waterEvery)===120?'selected':''}>A cada 2 horas</option><option value="180" ${Number(store.reminders.waterEvery)===180?'selected':''}>A cada 3 horas</option></select></div><label class="checkbox-line"><input type="checkbox" name="water" ${store.reminders.water?'checked':''}> Lembrar pausas para água</label><label class="checkbox-line" style="margin:12px 0"><input type="checkbox" name="snack" ${store.reminders.snack?'checked':''}> Lembrar lanches opcionais</label><div class="grid-two"><label class="mini-field">Lanche manhã<input type="time" name="snackAM" required value="${esc(store.reminders.snackAM)}"></label><label class="mini-field">Lanche tarde<input type="time" name="snackPM" required value="${esc(store.reminders.snackPM)}"></label></div><button class="btn teal block" type="submit" style="margin-top:13px">Salvar lembretes</button></form><div class="stack" style="margin-top:12px"><button class="btn outline block" data-action="notification-permission">Permitir alertas enquanto o app estiver aberto</button><button class="btn outline block" data-action="export-reminders">↓ Gerar agenda recorrente (.ics)</button></div><p class="footnote" style="margin:12px 0 0"><strong>Transparência:</strong> avisos do navegador funcionam somente enquanto o aplicativo está aberto/ativo. Não há servidor de push nesta versão. Para lembretes com o app fechado, importe o arquivo .ics em um calendário compatível e habilite seus alertas; confirme no próprio calendário se a importação recorrente funcionou.</p></div>
  <div class="section-heading"><h2>Checklist de hoje</h2><span class="badge-date">${total} de 4 hábitos</span></div><div class="card flat"><div class="progress-track" style="margin-top:0"><div style="width:${total*25}%"></div></div>${habits.map(([id,name])=>`<label class="habit"><input type="checkbox" data-input="habit" data-id="${id}" ${h[id]?'checked':''}><span>${esc(name)}</span></label>`).join('')}</div>
  <div class="section-heading"><h2>Proteína e força</h2></div><div class="card"><p class="small muted">Para adultos saudáveis fisicamente ativos, a ISSN apresenta uma faixa geral de <strong>1,4–2,0 g/kg/dia</strong>, não uma meta obrigatória nem individual.</p><div class="notice info">${weight>=20&&weight<=350?`Com ${fmtNum(weight)} kg informados, a faixa matemática seria ${Math.round(weight*1.4)}–${Math.round(weight*2)} g/dia.`:'Adicione seu peso no Perfil para visualizar uma faixa matemática de referência.'}</div><p class="footnote">Doença renal, gravidez, tratamentos ou necessidades específicas requerem avaliação clínica. Não há necessidade automática de suplemento.</p></div>
  <div class="section-heading"><h2>Fontes e método</h2></div><div class="card">${DB.references.map(ref=>`<div class="source-item"><a href="${ref.url}" target="_blank" rel="noopener noreferrer">${esc(ref.name)} ↗</a><span>${esc(ref.org)} · ${esc(ref.tag)}</span></div>`).join('')}<p class="footnote">Base: diretrizes e literatura científica, não endosso pessoal de nutricionistas ou educadores físicos. A versão ${DB.version} não atualiza a ciência automaticamente.</p></div>`;}

function helpPage(){return `${titleBlock('CENTRAL DE AJUDA','Manual do TRINCA 360.','Um guia dentro do próprio aplicativo, do primeiro acesso ao registro da sua evolução.')}
 <div class="help-intro"><strong>Comece por aqui</strong><p>Preencha o Perfil, escolha seu treino e registre somente o que realmente realizou. Se foi uma sessão diferente, utilize Treino avulso.</p><div class="quick-actions"><button class="btn teal" data-action="go-profile">Abrir Perfil</button><button class="btn outline" data-action="go-avulso">Registrar avulso</button></div></div>
 <div class="help-topics">
 <details open><summary>1. Instalar no celular</summary><div class="help-copy"><p>No Android, abra este endereço no Chrome, toque em ⋮ e procure <strong>Instalar app</strong> ou <strong>Adicionar à tela inicial</strong>. Confirme e abra pelo ícone TRINCA 360. O ZIP é para desenvolvimento, não para uso cotidiano.</p><button class="btn ghost smallbtn" data-action="install">Ver instruções de instalação</button></div></details>
 <details><summary>2. Preencher o Perfil e medir a cintura</summary><div class="help-copy"><p>Em Perfil, informe idade, peso, altura (cm), cintura (cm), nível de experiência, objetivo, data de início e duração desejada. Salve para calcular a fase atual. Meça a cintura com fita horizontal, sem apertar, no mesmo ponto nas próximas avaliações. Peso e medidas ajudam a acompanhar tendências, mas não definem cargas por si só.</p><button class="btn ghost smallbtn" data-action="go-profile">Abrir Perfil</button></div></details>
 <details><summary>3. Fazer as fichas A, B e C</summary><div class="help-copy"><p>Abra Treinos e escolha A, B ou C. Cada cartão informa quantas séries e repetições fazer. Marque S1, S2 etc. <strong>depois</strong> de executar cada série; registre carga e RIR (repetições que ainda conseguiria fazer com boa técnica). Use Como fazer para conferir a ilustração, instruções e vídeo externo. Ao terminar, toque em Registrar este treino e confirme tempo e cardio reais.</p><p>O modo de 30 minutos tem menos volume; em Perfil você pode escolher 45 ou 60 minutos. Não precisa chegar à falha muscular para progredir.</p><button class="btn ghost smallbtn" data-action="go-workouts">Abrir Treinos</button></div></details>
 <details><summary>4. Treinei peito + bíceps. Isso conta?</summary><div class="help-copy"><p><strong>Sim, quando você registrar.</strong> Escolha <strong>Treino avulso</strong>, marque Peito e Bíceps, informe os minutos reais de musculação e, se fez 10 minutos de esteira na mesma ida, coloque 10 em Cardio na mesma sessão. Isso adiciona uma sessão à frequência semanal e 10 minutos ao indicador de cardio, sem marcar A/B/C como concluídas.</p><p>O app não reconhece automaticamente atividades feitas fora dele. Não lance os mesmos 10 minutos novamente em Cardio extra.</p><button class="btn teal smallbtn" data-action="go-avulso">＋ Registrar treino avulso</button></div></details>
 <details><summary>5. Fiz só uma caminhada ou esteira</summary><div class="help-copy"><p>Vá em <strong>Evolução → Caminhadas e cardio extra</strong>, informe a data, a modalidade e os minutos. Isso soma ao cardio semanal, mas não cria uma sessão de musculação. Se você já registrou esses minutos dentro de outro treino, não repita.</p><button class="btn ghost smallbtn" data-action="go-progress">Abrir Evolução</button></div></details>
 <details><summary>6. Como acompanho séries, RIR e ciclos?</summary><div class="help-copy"><p>As cargas e séries efetivamente marcadas ficam no histórico após você salvar a sessão. RIR 2 significa encerrar a série acreditando que ainda conseguiria 2 repetições com boa técnica. O plano tem fases ao longo de 12 semanas e alterna a seleção de exercícios no ciclo seguinte; isso é um modelo de organização, não uma exigência de trocar tudo em data fixa.</p><button class="btn ghost smallbtn" data-action="go-progress">Meu histórico</button></div></details>
 <details><summary>7. Alimentação, água e lembretes</summary><div class="help-copy"><p>Na aba Nutrição há exemplos orientativos de café da manhã, almoço, lanches e jantar, inclusive alternativas vegetarianas. Não substituem uma prescrição individual de nutricionista. Registre água pelos botões +150 ml / +250 ml, conforme o que bebeu. Configure horários dos lembretes; os avisos internos funcionam enquanto o app estiver aberto e ativo. Para lembretes com ele fechado, exporte a agenda .ics e confira os alarmes no calendário em que a importar.</p><button class="btn ghost smallbtn" data-action="go-nutrition">Abrir Nutrição</button></div></details>
 <details><summary>8. Fazer avaliações físicas</summary><div class="help-copy"><p>Em Evolução, informe o peso e/ou cintura na data da medição. Tente comparar sempre nas mesmas condições. Observe também regularidade, fôlego, recuperação e cargas, não somente o peso.</p><button class="btn ghost smallbtn" data-action="go-progress">Registrar avaliação</button></div></details>
 <details><summary>9. Backup, atualização e privacidade</summary><div class="help-copy"><p>O histórico fica <strong>neste navegador/aparelho</strong>, não na página pública do GitHub. Em Perfil, exporte um backup .json regularmente e guarde-o em local privado. A opção Importar backup substitui os dados atuais. Não limpe os dados do site nem desinstale antes de exportar. Atualizações do código não sincronizam seus registros entre dispositivos. Vídeos externos precisam de internet.</p><button class="btn ghost smallbtn" data-action="go-profile">Ir aos backups</button></div></details>
 <details><summary>10. Segurança e limites do aplicativo</summary><div class="help-copy"><p>O TRINCA 360 é uma ferramenta de organização, não um monitor automático nem uma consulta médica ou nutricional. Não inventa repetições, intensidade, gasto calórico ou metas individuais. Peça ao educador físico para conferir a execução e adaptar os exercícios. Se sentir dor no peito, tontura importante ou falta de ar incomum, interrompa e procure avaliação apropriada.</p></div></details>
 </div><div class="help-outro">TRINCA 360 · versão ${DB.version}<br><strong>Desenvolvido por Anderson Gomes 🦫</strong></div>`;}

function profilePage(){const p=store.profile;return `${titleBlock('CONFIGURAÇÕES','O plano é seu.','Seu perfil, suas medidas e a duração do treino definem a proposta de progressão. Dados ficam neste navegador.')}
  <div class="card"><h3>Avaliação inicial e preferências</h3><form id="profile-form"><div class="form-field"><label for="p-name">Como quer ser chamado?</label><input id="p-name" type="text" name="name" maxlength="38" value="${esc(p.name)}" placeholder="Opcional"></div><div class="grid-two"><div class="form-field"><label for="p-age">Idade</label><input id="p-age" name="age" type="number" required min="18" max="100" value="${esc(p.age)}"></div><div class="form-field"><label for="p-weight">Peso (kg)</label><input id="p-weight" name="weight" type="number" min="20" max="350" step="0.1" value="${esc(p.weight)}" placeholder="Opcional"></div></div><div class="grid-two"><div class="form-field"><label for="p-height">Altura (cm)</label><input id="p-height" name="height" type="number" min="100" max="240" value="${esc(p.height)}" placeholder="Opcional"></div><div class="form-field"><label for="p-waist">Cintura (cm)</label><input id="p-waist" name="waist" type="number" min="30" max="220" step="0.1" value="${esc(p.waist||'')}" placeholder="Opcional"></div></div><div class="form-field"><label for="p-start">Início do programa (define as 12 semanas)</label><input id="p-start" type="date" name="startDate" max="${localDate()}" required value="${esc(p.startDate)}"></div><div class="form-field"><label for="p-level">Experiência com musculação</label><select name="experience" id="p-level"><option value="iniciante" ${p.experience==='iniciante'?'selected':''}>Nunca treinei / iniciante</option><option value="retomando" ${p.experience==='retomando'?'selected':''}>Retomando musculação</option><option value="ativo" ${p.experience==='ativo'?'selected':''}>Já treino regularmente</option></select></div><div class="form-field"><label for="p-goal">Objetivo principal</label><select name="goal" id="p-goal"><option value="definicao" ${p.goal==='definicao'?'selected':''}>Definição muscular</option><option value="condicionamento" ${p.goal==='condicionamento'?'selected':''}>Condicionamento</option><option value="forca" ${p.goal==='forca'?'selected':''}>Força e saúde</option></select></div><div class="form-field"><label for="p-duration">Quanto tempo você tem hoje?</label><select name="sessionLength" id="p-duration"><option value="30" ${p.sessionLength==='30'?'selected':''}>30 minutos — treino objetivo</option><option value="45" ${p.sessionLength==='45'?'selected':''}>45 minutos — 4 séries principais + 3 séries auxiliares</option><option value="60" ${p.sessionLength==='60'?'selected':''}>60 minutos — até 4 séries por exercício</option></select></div><div class="form-field"><label for="p-food">Preferência alimentar para exemplos de refeições</label><select name="foodStyle" id="p-food"><option value="geral" ${p.foodStyle==='geral'?'selected':''}>Geral (inclui alimentos de origem animal)</option><option value="vegetariano" ${p.foodStyle==='vegetariano'?'selected':''}>Vegetariana (com alternativas vegetais)</option></select></div><div class="form-field"><label for="p-restrictions">Alergias / restrições / cuidados (somente lembrete pessoal)</label><input name="restrictions" id="p-restrictions" maxlength="120" value="${esc(p.restrictions||'')}" placeholder="Ex.: não consumo lactose"></div><button class="btn teal block" type="submit">Salvar e ajustar meu plano</button></form><p class="footnote" style="margin:12px 0 0">O algoritmo adapta duração, ciclo, volume inicial e metas de esforço; peso, altura e cintura não determinam sozinhos uma prescrição segura. Para lesões, doenças, restrições ou dificuldades técnicas, peça avaliação profissional.</p></div>
  <div class="section-heading"><h2>Meu retrato atual</h2></div>${assessmentCard()}
  <div class="section-heading"><h2>Rotação em 12 semanas</h2></div><div class="card"><strong>Ciclo ${cycleNumber()} · Semana ${phaseWeek()}/12</strong><p class="small muted" style="margin-top:8px">${phaseTitle().title}. A cada 12 semanas o app alterna a seleção de exercícios e mantém seu histórico. Isso é um modelo de planejamento, não uma exigência fisiológica de trocar exercícios em data fixa. Reavalie seu progresso e consulte o instrutor.</p></div>
  <div class="section-heading"><h2>Instalar no celular</h2></div><div class="install-note"><div class="grow"><strong>Seu atalho de treino</strong><p>Abra via HTTPS, adicione à tela inicial e acesse os treinos salvos.</p></div><button class="btn ghost smallbtn" data-action="install">Instalar</button></div>
  <div class="section-heading"><h2>Manual e ajuda</h2></div><div class="card flat"><p class="small muted">Consulte instalação, fichas A/B/C, treino avulso, cardio, Nutrição, medidas, RIR e backup.</p><button class="btn teal block" data-action="go-help">❔ Abrir manual completo</button></div><div class="section-heading"><h2>Meus dados e backup</h2></div><div class="card"><p class="small muted">Histórico da versão anterior é preservado neste mesmo navegador. Antes de trocar de dispositivo, exporte o backup. Não há conta ou sincronização automática entre aparelhos.</p><div class="stack"><button class="btn outline block" data-action="export">↓ Exportar backup (.json)</button><label class="btn outline block" style="cursor:pointer">↑ Importar backup <input id="import-input" type="file" accept=".json,application/json" hidden></label><button class="btn warn block" data-action="delete-all">Apagar meus registros</button></div></div><div class="section-heading"><h2>Créditos</h2></div><div class="card"><div class="author-mark">Desenvolvido por Anderson Gomes 🦫</div><p class="footnote">TRINCA 360 · versão ${DB.version}. Referências científicas na área Nutrição. Sem vínculo, revisão individual ou endosso das instituições citadas.</p></div>`;}

function exerciseModal(id,day=ui.day){const ex=DB.exercises[id];if(!ex)return;$('#dialog-root').innerHTML=`<div class="modal-scrim" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="close" aria-label="Fechar" data-action="close-modal">×</button><div class="eyebrow">MOVIMENTO · ${esc(ex.group).toUpperCase()}</div><h2 id="modal-title">${esc(ex.name)}</h2><div class="pill-row"><span class="pill">${esc(ex.equipment)}</span><span class="pill gray">${setsFor(day,id)} × ${esc(repFor(id))}</span></div><img class="modal-hero" src="assets/exercises/${ex.image}.svg" alt="Desenho esquemático de ${esc(ex.name)}"><p class="footnote">Ilustração esquemática para reconhecimento; assista à demonstração para conferir o movimento.</p><h3>Execução passo a passo</h3><ol>${ex.steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol><div class="tip"><strong>✓ Dica técnica: </strong>${esc(ex.tip)}</div><div class="care"><strong>⚠ Atenção: </strong>${esc(ex.care)}</div><a class="btn teal block" href="${ex.video}" target="_blank" rel="noopener noreferrer" style="margin-top:14px">▶ Abrir vídeo demonstrativo ↗</a><p class="footnote" style="margin:8px 0 0;text-align:center">Vídeo hospedado no site externo MuscleWiki; necessita conexão.</p></div></div>`;}
function finishModal(day){const d=draftFor(day),count=completedSets(day);if(!count){notify('Marque ao menos uma série antes de registrar.');return;}const defaultDuration=ui.sessionSeconds>0?Math.max(1,Math.round(ui.sessionSeconds/60)):Number(store.profile.sessionLength);$('#dialog-root').innerHTML=`<div class="modal-scrim" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="finish-title"><button class="close" data-action="close-modal" aria-label="Fechar">×</button><div class="eyebrow">REGISTRO DA SESSÃO</div><h2 id="finish-title">Treino ${day} concluído?</h2><p class="small muted">Você marcou ${count} de ${targetSets(day)} séries. Confirme apenas o que realizou; registros parciais também contam no histórico.</p><form id="finish-form"><input type="hidden" name="day" value="${day}"><div class="form-field"><label for="finish-duration">Tempo realizado (minutos)</label><input id="finish-duration" name="duration" type="number" min="1" max="300" value="${defaultDuration}" required></div><div class="form-field"><label for="finish-cardio">Cardio efetivamente realizado (minutos)</label><input id="finish-cardio" name="cardio" type="number" min="0" max="300" value="0" required></div><div class="form-field"><label for="finish-note">Observação (opcional)</label><textarea id="finish-note" name="note" maxlength="300" placeholder="Como foi o treino?"></textarea></div><button class="btn teal block" type="submit">✓ Salvar meu treino</button></form></div></div>`;}
function genericModal(title,body,buttons=''){ $('#dialog-root').innerHTML=`<div class="modal-scrim" data-action="close-modal"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="generic-title"><button class="close" data-action="close-modal" aria-label="Fechar">×</button><h2 id="generic-title">${esc(title)}</h2><p class="small muted">${body}</p>${buttons}</div></div>`;}
function closeModal(){$('#dialog-root').innerHTML='';}
function toClock(sec){return `${String(Math.floor(Math.max(0,sec)/60)).padStart(2,'0')}:${String(Math.max(0,sec)%60).padStart(2,'0')}`;}
function doTick(){if(ui.sessionRunning)ui.sessionSeconds++;if(ui.restRunning){ui.restSeconds=Math.max(0,ui.restSeconds-1);if(ui.restSeconds===0){ui.restRunning=false;notify('Intervalo concluído!');}}const s=$('#clock-session'),r=$('#clock-rest');if(s)s.textContent=toClock(ui.sessionSeconds);if(r)r.textContent=toClock(ui.restSeconds);}
function render(){const main=$('#app-main');if(!main)return;main.innerHTML=ui.page==='home'?home():ui.page==='workouts'?workoutPage():ui.page==='progress'?progressPage():ui.page==='nutrition'?nutritionPage():ui.page==='help'?helpPage():ui.page==='avulso'?avulsoPage():profilePage();document.querySelectorAll('[data-nav]').forEach(b=>{const sel=b.dataset.nav===ui.page;b.classList.toggle('active',sel);if(sel)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});const badge=$('#network-pill');if(badge){badge.textContent=navigator.onLine?'● Online':'● Offline';badge.classList.toggle('offline',!navigator.onLine);}}
function confirmDelete(){genericModal('Apagar todos os registros?','Isso removerá seus treinos, medidas, caminhadas, perfil e hábitos deste navegador. Se quiser preservar algo, exporte um backup antes.','<div class="stack"><button class="btn warn block" data-action="delete-confirm">Sim, apagar tudo</button><button class="btn outline block" data-action="close-modal">Cancelar</button></div>');}
function exportData(){const blob=new Blob([JSON.stringify({app:'TRINCA360',schema:1,exportedAt:new Date().toISOString(),data:store},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`Trinca360_backup_${localDate()}.json`;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),4000);notify('Backup exportado. Guarde em local seguro.');}
function validImport(data){return data&&data.app==='TRINCA360'&&data.schema===1&&data.data&&typeof data.data==='object'&&data.data.profile&&Array.isArray(data.data.sessions)&&Array.isArray(data.data.measures)&&Array.isArray(data.data.walks)&&data.data.sessions.length<20000&&data.data.measures.length<20000&&data.data.walks.length<20000;}
function install(){if(ui.installPrompt){ui.installPrompt.prompt();ui.installPrompt.userChoice.then(()=>ui.installPrompt=null);return;}genericModal('Como instalar no celular','O aplicativo deve estar publicado em um endereço HTTPS (por exemplo, GitHub Pages). No Android, abra no Chrome e use ⋮ > Adicionar à tela inicial ou Instalar app. No iPhone, use Compartilhar > Adicionar à Tela de Início. Arquivos abertos diretamente do ZIP não podem ser instalados como PWA.','<button class="btn teal block" data-action="close-modal">Entendi</button>');}
function handleClick(ev){const a=ev.target.closest('[data-action]');if(!a)return;const action=a.dataset.action,id=a.dataset.id,day=a.dataset.day,index=Number(a.dataset.index);if(action==='close-modal'){if(ev.target.classList.contains('modal-scrim')||a.classList.contains('close')||a.dataset.action==='close-modal'&&a.tagName==='BUTTON')closeModal();return;}switch(action){case 'go-help':setNav('help');break;case 'go-avulso':setNav('avulso');break;case 'go-progress':setNav('progress');break;case 'go-profile':setNav('profile');break;case 'go-workouts':setNav('workouts');break;case 'go-nutrition':setNav('nutrition');break;case 'water-add':store.hydration[localDate()]=waterAmount()+Number(a.dataset.ml);save();render();notify('Água registrada!');break;case 'water-undo':store.hydration[localDate()]=Math.max(0,waterAmount()-250);save();render();break;case 'export-reminders':exportReminders();break;case 'notification-permission':if(!('Notification' in window)){notify('Alertas do navegador indisponíveis neste aparelho.');break;}Notification.requestPermission().then(v=>{store.reminders.notifications=v==='granted';save();notify(v==='granted'?'Alertas permitidos enquanto o app estiver aberto.':'Use a agenda .ics para lembretes externos.');});break;case 'open-day':setDay(day);break;case 'exercise-detail':exerciseModal(id,day||ui.day);break;case 'set-toggle':{const d=draftFor(day);d[id].sets[index]=!d[id].sets[index];save();render();break;}case 'session-toggle':ui.sessionRunning=!ui.sessionRunning;render();break;case 'session-reset':ui.sessionRunning=false;ui.sessionSeconds=0;render();break;case 'rest-toggle':if(ui.restSeconds===0)ui.restSeconds=store.profile.sessionLength==='30'?60:90;ui.restRunning=!ui.restRunning;render();break;case 'rest-reset':ui.restRunning=false;ui.restSeconds=store.profile.sessionLength==='30'?60:90;render();break;case 'finish-start':finishModal(day);break;case 'install':install();break;case 'export':exportData();break;case 'delete-all':confirmDelete();break;case 'delete-confirm':{store=structuredClone(DEFAULTS);save();ui.day='A';ui.sessionRunning=false;ui.sessionSeconds=0;closeModal();setNav('home');notify('Registros apagados deste aparelho.');break;}case 'remove-cardio':{if(confirm('Excluir este registro de cardio extra?')){store.walks=store.walks.filter(w=>String(w.id)!==String(id));save();render();notify('Cardio extra excluído.');}break;}case 'remove-measure':{if(confirm('Excluir esta avaliação?')){store.measures=store.measures.filter(m=>m.id!==id);save();render();notify('Avaliação excluída.');}break;}}}
function submitHandler(e){const form=e.target;if(!['profile-form','measure-form','walk-form','finish-form','reminders-form','avulso-form'].includes(form.id))return;e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);if(form.id==='reminders-form'){if(parseClock(f.get('start'))>=parseClock(f.get('end'))){notify('O fim do período deve ser depois do início.');return;}store.reminders={...store.reminders,enabled:!!f.get('enabled'),water:!!f.get('water'),snack:!!f.get('snack'),start:String(f.get('start')),end:String(f.get('end')),waterEvery:Number(f.get('waterEvery')),snackAM:String(f.get('snackAM')),snackPM:String(f.get('snackPM'))};save();render();notify('Horários de lembretes salvos.');return;}if(form.id==='profile-form'){const age=Number(f.get('age')),startDate=String(f.get('startDate'));if(!(age>=18&&age<=100)||startDate>localDate()){notify('Revise idade e data de início.');return;}store.profile={name:String(f.get('name')).trim().slice(0,38),age,weight:String(f.get('weight')),height:String(f.get('height')),waist:String(f.get('waist')),experience:String(f.get('experience')),goal:String(f.get('goal')),sessionLength:String(f.get('sessionLength')),foodStyle:String(f.get('foodStyle')),restrictions:String(f.get('restrictions')).trim().slice(0,120),startDate};save();render();notify('Perfil salvo!');return;}
if(form.id==='measure-form'){const date=String(f.get('date')),weight=Number(f.get('weight')),waist=Number(f.get('waist'));if(date>localDate()||(!weight&&!waist)){notify('Informe ao menos peso ou cintura em data válida.');return;}if((weight&&(weight<20||weight>350))||(waist&&(waist<30||waist>220))){notify('Confira os valores informados.');return;}store.measures=store.measures.filter(m=>m.date!==date);store.measures.push({id:crypto.randomUUID?crypto.randomUUID():String(Date.now()),date,weight:weight||null,waist:waist||null});save();render();notify('Avaliação salva.');return;}
if(form.id==='walk-form'){const date=String(f.get('date')),minutes=Number(f.get('minutes'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>localDate()||minutes<1||minutes>600||!Number.isInteger(minutes)){notify('Confira data e minutos.');return;}store.walks.push({id:`cardio-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,date,minutes,type:String(f.get('type')||'Cardio').slice(0,40)});save();render();notify('Cardio independente registrado!');return;}
if(form.id==='avulso-form'){const date=String(f.get('date')),groups=f.getAll('groups').map(String).filter(g=>['Peito','Costas','Bíceps','Tríceps','Pernas','Ombros','Abdômen','Glúteos','Corpo inteiro','Outro'].includes(g)),strength=Number(f.get('strength')),cardio=Number(f.get('cardio'));if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||date>localDate()||!groups.length||!Number.isInteger(strength)||strength<1||strength>300||!Number.isInteger(cardio)||cardio<0||cardio>300||strength+cardio>300){notify('Marque um grupo e confira data e minutos (total até 300).');return;}const note=String(f.get('note')||'').trim().slice(0,300),kind=String(f.get('cardioType')||'Esteira').slice(0,40);store.sessions.push({id:`avulso-${Date.now()}-${Math.random().toString(36).slice(2,7)}`,type:'avulso',date,day:'AVULSO',groups:[...new Set(groups)],strengthMin:strength,cardioMin:cardio,cardioType:cardio?kind:null,durationMin:strength+cardio,doneSets:null,partial:false,note,exercises:{}});if(!save()){store.sessions.pop();return;}setNav('progress');notify('Treino avulso e cardio registrado(s) sem duplicidade!');return;}
if(form.id==='finish-form'){const day=String(f.get('day')),durationMin=Number(f.get('duration')),cardioMin=Number(f.get('cardio'));if(!DB.programs[day]||!Number.isFinite(durationMin)||durationMin<1||durationMin>300||!Number.isFinite(cardioMin)||cardioMin<0||cardioMin>durationMin){notify('Confira a duração e o cardio (não pode superar a sessão).');return;}const d=draftFor(day),sets=Object.fromEntries(program(day).exercises.map(id=>[id,{setsDone:d[id].sets.slice(0,setsFor(day,id)).filter(Boolean).length,weight:d[id].weight||null,rir:d[id].rir===''?null:Number(d[id].rir),planned:setsFor(day,id),reps:repFor(id)}])),doneSets=completedSets(day),partial=doneSets<targetSets(day);store.sessions.push({id:`${Date.now()}-${Math.random().toString(36).slice(2,7)}`,date:localDate(),day,durationMin,cardioMin,note:String(f.get('note')).slice(0,300),doneSets,partial,cycle:cycleNumber(),week:phaseWeek(),durationMode:store.profile.sessionLength,exercises:sets});delete store.drafts[day];ui.sessionRunning=false;ui.sessionSeconds=0;ui.restRunning=false;ui.restSeconds=store.profile.sessionLength==='30'?60:90;save();closeModal();setNav('progress');notify(partial?'Treino parcial registrado.':'Treino completo registrado!');return;}}
function handleInput(e){const t=e.target;if(t.dataset.input==='rir'){draftFor(t.dataset.day)[t.dataset.id].rir=t.value;save();}if(t.dataset.input==='weight'){const v=t.value;const day=t.dataset.day,id=t.dataset.id;const num=Number(v);if(v!==''&&(!Number.isFinite(num)||num<0||num>500)){notify('Informe uma carga entre 0 e 500 kg.');return;}draftFor(day)[id].weight=v;save();}if(t.dataset.input==='habit'){const date=localDate(),id=t.dataset.id;if(!store.habits[date])store.habits[date]={};store.habits[date][id]=t.checked;save();render();}}
async function importFile(file){if(!file)return;try{if(file.size>5_000_000){notify('Backup grande demais (máx. 5 MB).');return;}const obj=JSON.parse(await file.text());if(!validImport(obj)){notify('Arquivo não é um backup TRINCA 360 válido.');return;}if(!confirm('Importar substituirá TODOS os registros atuais deste navegador. Deseja continuar?'))return;const data=obj.data;store={...structuredClone(DEFAULTS),...data,profile:{...DEFAULTS.profile,...data.profile},drafts:data.drafts&&typeof data.drafts==='object'?data.drafts:{},habits:data.habits&&typeof data.habits==='object'?data.habits:{},hydration:data.hydration&&typeof data.hydration==='object'?data.hydration:{},reminders:{...DEFAULTS.reminders,...(data.reminders||{})},seenReminders:data.seenReminders&&typeof data.seenReminders==='object'?data.seenReminders:{}};save();setNav('home');notify('Backup importado com sucesso!');}catch(e){notify('Não foi possível ler este backup.');}}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();ui.installPrompt=e;});
window.addEventListener('online',render);window.addEventListener('offline',render);
document.addEventListener('click',handleClick);
document.addEventListener('submit',submitHandler);
document.addEventListener('change',e=>{handleInput(e);if(e.target.id==='import-input')importFile(e.target.files?.[0]);});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();});
document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>setNav(b.dataset.nav)));
if('serviceWorker' in navigator&&window.isSecureContext)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(e=>console.warn('PWA indisponível',e)));
tickId=setInterval(doTick,1000);setInterval(remindWhenOpen,30000);remindWhenOpen();
render();
})();
